// isPrivateIP checks if the given hostname resolves to a private IP address
func isPrivateIP(hostname string) bool {
	// Simple check for common private hostnames
	privateHosts := []string{
		"localhost",
		"127.0.0.1",
		"::1",
		"0.0.0.0",
	}

	for _, h := range privateHosts {
		if hostname == h {
			return true
		}
	}

	// Check for private IP ranges
	ips, err := net.LookupIP(hostname)
	if err != nil {
		return false
	}

	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {
			return true
		}
	}

	return false
}

