// fetchURLContent fetches the content from the provided URL and extracts title and meta description
func fetchURLContent(url string) (string, string, error) {
	// Create fasthttp client with timeout and dual stack
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
		ReadTimeout:  3 * time.Second,
		WriteTimeout: 3 * time.Second,
	}

	// Create request
	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	req.SetRequestURI(url)
	req.Header.SetMethod("GET")
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; FetchURLPreview/1.0)")

	// Create response
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Perform the request with redirects
	err := client.DoRedirects(req, resp, 5) // Allow up to 5 redirects
	if err != nil {
		return "", "", fmt.Errorf("request failed: %v", err)
	}

	// Check status code
	statusCode := resp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		return "", "", fmt.Errorf("unexpected status code: %d", statusCode)
	}

	// Get response body
	body := resp.Body()
	if len(body) == 0 {
		return "", "", fmt.Errorf("empty response body")
	}

	// Parse HTML to extract title and meta description
	title, description := parseHTML(string(body))

	return title, description, nil
}

// parseHTML parses HTML content and extracts the page title and meta description
func parseHTML(htmlContent string) (string, string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
