// FetchURLPreview handles POST requests to fetch URL previews
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only accept POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: "Only POST method is allowed",
		})
		return
	}

	// Parse request body
	var reqBody RequestBody
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: fmt.Sprintf("Invalid JSON body: %v", err),
		})
		return
	}

	// Validate URL
	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: "URL field is required",
		})
		return
	}

	// Create fasthttp client with timeout and dual stack dial
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Create request
	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod("GET")

	// Set timeout for the request
	timeout := 3 * time.Second
	_ = timeout

	// Execute request with redirects and timeout
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	err := client.DoRedirects(req, resp, 5)
	if err != nil {
		// Check if it's a timeout error
		if strings.Contains(err.Error(), "timeout") || strings.Contains(err.Error(), "deadline") {
			ctx.SetStatusCode(fasthttp.StatusGatewayTimeout)
			ctx.SetContentType("application/json")
			json.NewEncoder(ctx).Encode(ResponseBody{
				URL:   reqBody.URL,
				Error: "Request timed out after 3 seconds",
			})
			return
		}

		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ResponseBody{
			URL:   reqBody.URL,
			Error: fmt.Sprintf("Failed to fetch URL: %v", err),
		})
		return
	}

	// Check response status code
	statusCode := resp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ResponseBody{
			URL:   reqBody.URL,
			Error: fmt.Sprintf("Received non-200 status code: %d", statusCode),
		})
		return
	}

	// Read response body
	bodyBytes := resp.Body()
	if len(bodyBytes) == 0 {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(ResponseBody{
			URL:   reqBody.URL,
			Error: "Empty response body",
		})
		return
	}

	// Parse HTML to extract title and meta description
	title, description := parseHTML(string(bodyBytes))

	// Return successful response
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	json.NewEncoder(ctx).Encode(ResponseBody{
		URL:         reqBody.URL,
		Title:       title,
		Description: description,
	})
}

// parseHTML extracts the title and meta description from HTML content
func parseHTML(htmlContent string) (string, string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	var title, description string

	// Traverse the HTML tree
	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if n.FirstChild != nil {
					title = strings.TrimSpace(n.FirstChild.Data)
				}
			case "meta":
				var name, content string
				for _, attr := range n.Attr {
					switch attr.Key {
					case "name":
						name = strings.ToLower(attr.Val)
					case "content":
						content = attr.Val
					}
				}
				if name == "description" && content != "" {
					description = content
				}
			}
		}

		// Continue traversing children
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}

	traverse(doc)
	return title, description
}

// main function for demonstration purposes
func main() {
	// Create fasthttp server
	server := &fasthttp.Server{
		Handler: func(ctx *fasthttp.RequestCtx) {
			switch string(ctx.Path()) {
			case "/fetch-preview":
				FetchURLPreview(ctx)
			default:
				ctx.SetStatusCode(fasthttp.StatusNotFound)
				ctx.SetContentType("application/json")
				json.NewEncoder(ctx).Encode(map[string]string{
					"error": "Endpoint not found",
				})
			}
		},
	}

	// Start server on port 8080
	fmt.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

