	}
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &request); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"invalid JSON body"}`)
		return
	}

	// Validate URL
	if request.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"url field is required"}`)
		return
	}

	// Create fasthttp client with DualStack dial
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Create request to fetch the URL
	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	req.SetRequestURI(request.URL)
	req.Header.SetMethod("GET")
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Create response object
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Perform the request with redirects
	if err := client.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"failed to fetch URL: ` + err.Error() + `"}`)
		return
	}

	// Read response body
	bodyBytes := make([]byte, 0)
	bodyBytes = append(bodyBytes, resp.Body()...)

	// Parse HTML to extract title and meta description
	title, description := extractMeta(bodyBytes)

	// Prepare response
	response := struct {
		URL         string `json:"url"`
		Title       string `json:"title"`
		Description string `json:"description"`
	}{
		URL:         request.URL,
		Title:       title,
		Description: description,
	}

	// Return JSON response
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	jsonBytes, _ := json.Marshal(response)
	ctx.SetBody(jsonBytes)
}

// extractMeta parses HTML and extracts title and meta description
func extractMeta(htmlContent []byte) (string, string) {
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(htmlContent)))
	if err != nil {
		return "", ""
	}

	// Extract title
	title := ""
	doc.Find("title").Each(func(i int, s *goquery.Selection) {
		title = strings.TrimSpace(s.Text())
	})

	// Extract meta description
	description := ""
	doc.Find("meta[name=description]").Each(func(i int, s *goquery.Selection) {
		if content, exists := s.Attr("content"); exists {
