	"golang.org/x/net/html"
)

// RequestBody represents the incoming JSON request
type RequestBody struct {
	URL string `json:"url"`
}

// ResponseBody represents the JSON response
type ResponseBody struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

// FetchURLPreview handles POST requests to fetch URL preview
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only accept POST requests
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: "Only POST method is allowed",
		})
		return
	}

	// Parse request body
	var reqBody RequestBody
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: fmt.Sprintf("Invalid JSON body: %v", err),
		})
		return
	}

	// Validate URL
	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: "URL field is required",
		})
		return
	}

	// Create fasthttp client with dual stack dial
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Create request
	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod("GET")
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Create response
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Fetch the URL with redirect support
	if err := client.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: fmt.Sprintf("Failed to fetch URL: %v", err),
		})
		return
	}

	// Check response status code
	if resp.StatusCode() != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: fmt.Sprintf("URL returned status code %d", resp.StatusCode()),
		})
		return
	}

	// Read response body
	body := resp.Body()
	if len(body) == 0 {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		json.NewEncoder(ctx).Encode(ResponseBody{
			Error: "Empty response body",
		})
		return
	}

	// Parse HTML to extract title and meta description
	title, description := parseHTML(body)

	// Return success response
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	json.NewEncoder(ctx).Encode(ResponseBody{
		Title:       title,
		Description: description,
	})
}

// parseHTML extracts title and meta description from HTML content
func parseHTML(body []byte) (string, string) {
	title := ""
	description := ""

	doc, err := html.Parse(strings.NewReader(string(body)))
	if err != nil {
		return title, description
	}

	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if n.FirstChild != nil {
					title = strings.TrimSpace(n.FirstChild.Data)
				}
			case "meta":
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = strings.ToLower(attr.Val)
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && content != "" {
					description = strings.TrimSpace(content)
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	return title, description
}

// main function to start the server
func main() {
	// Create fasthttp server
	server := &fasthttp.Server{
		Handler: func(ctx *fasthttp.RequestCtx) {
			// Route to FetchURLPreview handler
			if string(ctx.Path()) == "/fetch-preview" {
				FetchURLPreview(ctx)
				return
			}
			// Default 404
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			io.WriteString(ctx, "Not Found")
		},
	}

	// Start server on port 8080
	fmt.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}

