    // Create fasthttp server
    server := &fasthttp.Server{
        Handler: func(ctx *fasthttp.RequestCtx) {
            // Route to FetchURLPreview for /preview endpoint
            if string(ctx.Path()) == "/preview" {
                FetchURLPreview(ctx)
                return
            }

