        ctx.SetContentType("application/json")
        ctx.SetBodyString(fmt.Sprintf(`{"error":"invalid JSON: %s"}`, err.Error()))
        return
    }

    if request.URL == "" {
        ctx.SetStatusCode(fasthttp.StatusBadRequest)
        ctx.SetContentType("application/json")
        ctx.SetBodyString(`{"error":"url field is required"}`)
        return
    }

    // Configure fasthttp client with timeout and dual stack dial
    client := &fasthttp.Client{
        Dial: fasthttp.DialDualStack,
    }

    // Create request
    req := fasthttp.AcquireRequest()
    defer fasthttp.ReleaseRequest(req)

    req.SetRequestURI(request.URL)
    req.Header.SetMethod("GET")
    req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; FetchURLPreview/1.0)")

    // Create response
    resp := fasthttp.AcquireResponse()
    defer fasthttp.ReleaseResponse(resp)

    // Fetch URL with redirects and 3-second timeout
    err := client.DoRedirects(req, resp, 10)
    if err != nil {
        ctx.SetStatusCode(fasthttp.StatusBadGateway)
        ctx.SetContentType("application/json")
        ctx.SetBodyString(fmt.Sprintf(`{"error":"failed to fetch URL: %s"}`, err.Error()))
        return
    }

    // Check response status code
    statusCode := resp.StatusCode()
    if statusCode != fasthttp.StatusOK {
        ctx.SetStatusCode(fasthttp.StatusBadGateway)
        ctx.SetContentType("application/json")
        ctx.SetBodyString(fmt.Sprintf(`{"error":"unexpected status code: %d"}`, statusCode))
        return
    }

    // Read response body
    body := resp.Body()
    if len(body) == 0 {
        ctx.SetStatusCode(fasthttp.StatusBadGateway)
        ctx.SetContentType("application/json")
        ctx.SetBodyString(`{"error":"empty response body"}`)
        return
    }

    // Parse HTML to extract title and meta description
    title, description := parseHTML(body)

    // Return result as JSON
    result := struct {
