// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	// Read all content
	data, err := io.ReadAll(r)
	if err != nil {
		return "", "", err
	}

	content := string(data)

	// Extract title
	titleStart := strings.Index(strings.ToLower(content), "<title")
	if titleStart != -1 {
		// Find the closing > of the title tag
		titleTagEnd := strings.Index(content[titleStart:], ">")
		if titleTagEnd != -1 {
			titleContentStart := titleStart + titleTagEnd + 1
			titleEnd := strings.Index(content[titleContentStart:], "</title>")
			if titleEnd != -1 {
				title = strings.TrimSpace(content[titleContentStart : titleContentStart+titleEnd])
			}
		}
	}

	// Extract meta description
	metaTag := `<meta`
	metaEnd := `>`
	descriptionAttr := `name="description"`
	contentAttr := `content="`

	searchPos := 0
	for {
		metaStart := strings.Index(strings.ToLower(content[searchPos:]), metaTag)
		if metaStart == -1 {
			break
		}
		metaStart += searchPos
		metaTagEnd := strings.Index(content[metaStart:], metaEnd)
		if metaTagEnd == -1 {
			break
		}
		metaContent := content[metaStart : metaStart+metaTagEnd+1]

		if strings.Contains(strings.ToLower(metaContent), descriptionAttr) {
			contentStart := strings.Index(metaContent, contentAttr)
			if contentStart != -1 {
				contentStart += len(contentAttr)
				contentEnd := strings.Index(metaContent[contentStart:], `"`)
				if contentEnd != -1 {
					description = strings.TrimSpace(metaContent[contentStart : contentStart+contentEnd])
					break
				}
			}
		}
		searchPos = metaStart + metaTagEnd + 1
	}

	return title, description, nil
}

